import type { Record } from '../db'

type JsInclude = Now.Internal.WithID<{
    /** The name of the JavaScript include (required) */
    name: string
    /** The URL of the JavaScript include (cannot be used with `sysUiScript`) */
    url?: string
    /** The sys_ui_script reference for the JavaScript include (cannot be used with `url`) */
    sysUiScript?: string | Record<'sys_ui_script'>
}>

type CssInclude = Now.Internal.WithID<{
    /** The name of the CSS include (required) */
    name: string
    /** The URL of the CSS include (cannot be used with `spCss`) */
    url?: string
    /** The sp_css reference for the CSS include (cannot be used with `url`) */
    spCss?: string | Record<'sp_css'>
    /** The URL of the RTL CSS include */
    rtlCssUrl?: string
    /** Whether the CSS include should be lazy loaded (default is false) */
    lazyLoad?: boolean
}>

type JsReference = string | Record<'sp_js_include'> | JsInclude
type CssReference = string | Record<'sp_css_include'> | CssInclude
type JsIncludeWithOrder = {
    order: number
    include: JsReference
}
type CssIncludeWithOrder = {
    order: number
    include: CssReference
}

export type SPWidgetDependency = Now.Internal.WithID<
    {
        /** The name of the widget dependency (required) */
        name: string
        /** The Angular module name for the widget dependency */
        angularModuleName?: string
        /** Whether the widget should be included on page load (default is false) */
        includeOnPageLoad?: boolean
        /** An array of CSS includes for the widget dependency */
        cssIncludes?: CssIncludeWithOrder[]
        /** An array of JavaScript includes for the widget dependency */
        jsIncludes?: JsIncludeWithOrder[]
        /** An array of portals for the widget dependency */
        portalsForPageLoad?: (string | Record<'sp_portal'>)[]
    } & Now.Internal.Meta
>

/**
 * API used to create a Service Portal widget dependency (`sp_widget_dependency`). For
 * more information, see the {@link https://docs.servicenow.com/csh?version=latest&topicname=fluent-service-portal-api.html#fluent-sp-widget-dependency-object|ServiceNow docs}.
 */
export function SPWidgetDependency(config: SPWidgetDependency) {
    return config
}

export function JsInclude(config: JsInclude) {
    return config
}

export function CssInclude(config: CssInclude) {
    return config
}
